style.css:
@-moz-document domain("pokemonshowdown.com") {
/* Fundo geral */
  body, .ps-room {
    background-color: #101010 !important;
    color: #f2f2f2 !important;
    font-family: 'Verdana', sans-serif !important;
  }

  /* Caixa principal da batalha */
  .battle {
    background: linear-gradient(to bottom, #1c1c1c 0%, #0e0e0e 100%) !important;
    border: 2px solid #2e2e2e !important;
    box-shadow: 0 0 20px #0008 inset;
  }

  /* Campo de batalha */
  .battlecanvas {
    background-color: #181818 !important;
    background-image: radial-gradient(circle at center, #222 0%, #111 100%) !important;
    border-radius: 8px !important;
    border: 1px solid #333 !important;
  }

  /* Chat */
  .chat {
    background-color: #0d0d0d !important;
    border-left: 1px solid #333 !important;
    color: #dcdcdc !important;
  }

  .chat-message, .chat-log {
    background: none !important;
  }

  /* Barra de HP estilo BW */
  .hpbar {
    border: 1px solid #555 !important;
    border-radius: 6px !important;
    background-color: #222 !important;
  }

  .hpbar .hptext {
    color: #fff !important;
    font-weight: bold !important;
    text-shadow: 0 0 2px #000 !important;
  }

  .hpbar .bar {
    border-radius: 6px !important;
    background: linear-gradient(to right, #70ff70, #4ac04a) !important;
  }

  /* Botões */
  button, .button, .teamicons {
    background-color: #1c1c1c !important;
    border: 1px solid #333 !important;
    border-radius: 6px !important;
    color: #e8e8e8 !important;
    transition: background-color 0.2s ease;
  }

  button:hover, .button:hover {
    background-color: #2a2a2a !important;
  }

  /* Inputs */
  input, select {
    background-color: #181818 !important;
    border: 1px solid #333 !important;
    color: #fff !important;
  }

  /* Painel de comandos */
  .controls {
    background-color: #111 !important;
    border-top: 1px solid #333 !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px !important;
  }
  ::-webkit-scrollbar-track {
    background: #0b0b0b !important;
  }
  ::-webkit-scrollbar-thumb {
    background: #444 !important;
    border-radius: 8px !important;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #666 !important;
  }

  /* Nome dos Pokémon */
  .trainer strong, .trainer span, .username {
    color: #f0f0f0 !important;
    text-shadow: 0 0 3px #000 !important;
  }

  /* Efeitos sutis nas barras */
  .hpbar .inner {
    box-shadow: 0 0 5px #0006 inset;
  }
}
